const txt=text=>({type:'text',text});
const link=r=>({type:'text',text:r.identifier,marks:[{type:'link',attrs:{href:'https://roadmap.astforum.ru/work_packages/'+r.identifier+'/activity',title:null}}]});
(async()=>{
const user=await User.findOne({where:{id:'4cf44904-6c72-4da7-b285-824fb455906a'}});if(!user)throw Error('User missing');
await sequelize.transaction(async transaction=>{
 for(const old of before){
  const doc=await Document.unscoped().findOne({where:{id:old.id},transaction,lock:{of:Document,level:transaction.LOCK.UPDATE}});
  if(JSON.stringify(doc.content)!==JSON.stringify(old.content))throw Error('Concurrent change '+doc.title);
  const content=JSON.parse(JSON.stringify(doc.content));
  const row=rows.find(r=>r.outline_id===doc.id);
  if(row){
   const para=content.content[0];let found=false;
   for(const n of para.content||[]){if(n.type==='text'&&n.text==='Задача: '){found=true;}}
   if(!found)throw Error('Task header missing');
   para.content.push(link(row));
  }else{
   const table=content.content.find(n=>n.type==='table');if(!table||table.content.length!==5)throw Error('Unexpected story table');
   for(let i=0;i<4;i++){
    table.content[i+1].content[2].content=[{type:'paragraph',content:[link(rows[i])]}];
    table.content[i+1].content[3].content=[{type:'paragraph',content:[txt(rows[i].hours+' ч (предварительно)')]}];
   }
  }
  const pm=require('/opt/outline/node_modules/prosemirror-model').Node.fromJSON(schema,content);
  const ydoc=new Y.Doc();if(doc.state)Y.applyUpdate(ydoc,doc.state);
  updateYFragment(ydoc,ydoc.getXmlFragment('default'),pm,{mapping:new Map(),isOMark:new Map()});
  doc.content=content;doc.text=serializer.serialize(pm);doc.state=Buffer.from(Y.encodeStateAsUpdate(ydoc));doc.changed('state',true);
  const ctx={state:{auth:{user},transaction},context:{auth:{user},transaction,ip:'127.0.0.1'}};
  await updater(ctx,{document:doc});ydoc.destroy();
 }
});
console.log('Updated 5 Outline documents');setTimeout(()=>process.exit(),300);
})().catch(e=>{console.error(e);process.exit(1)});
